using Microsoft.Data.Sqlite;
using MiniPharmacie.Business.Models;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Business.Services;

public sealed class StockManagementService(DatabaseInitializer database)
{
    public async Task<long> SaveProductAsync(ProductDraft p,long userId,long? id=null,CancellationToken ct=default)
    {
        if(string.IsNullOrWhiteSpace(p.Code)||string.IsNullOrWhiteSpace(p.Name)||string.IsNullOrWhiteSpace(p.Unit)||p.SalePriceMinor<0||p.ReorderLevel<0) throw new ArgumentException("Vérifiez la référence, la désignation, l'unité, le prix et le seuil.");
        await using var c=database.CreateConnection(); await c.OpenAsync(ct); await SecurityAdministrationService.RequireManager(c,userId,ct); await using var cmd=c.CreateCommand();
        cmd.CommandText=id is null?"INSERT INTO Products(Code,Name,CategoryId,Dosage,PharmaceuticalForm,Unit,SalePriceMinor,ReorderLevel,Barcode,ShelfLocation) VALUES($code,$name,$category,$dosage,$form,$unit,$price,$threshold,$barcode,$shelf);SELECT last_insert_rowid();":"UPDATE Products SET Code=$code,Name=$name,CategoryId=$category,Dosage=$dosage,PharmaceuticalForm=$form,Unit=$unit,SalePriceMinor=$price,ReorderLevel=$threshold,Barcode=$barcode,ShelfLocation=$shelf WHERE Id=$id;SELECT $id;";
        Add(cmd,"$code",p.Code.Trim());Add(cmd,"$name",p.Name.Trim());Add(cmd,"$category",(object?)p.CategoryId??DBNull.Value);Add(cmd,"$dosage",p.Dosage);Add(cmd,"$form",p.PharmaceuticalForm);Add(cmd,"$unit",p.Unit);Add(cmd,"$price",p.SalePriceMinor);Add(cmd,"$threshold",p.ReorderLevel);Add(cmd,"$barcode",(object?)p.Barcode??DBNull.Value);Add(cmd,"$shelf",(object?)p.ShelfLocation??DBNull.Value);if(id is not null)Add(cmd,"$id",id.Value);
        try{var saved=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));await using var audit=c.CreateCommand();audit.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,EntityId,OccurredAt,Details) VALUES($u,$a,'Products',$id,$d,$details)";audit.Parameters.AddWithValue("$u",userId);audit.Parameters.AddWithValue("$a",id is null?"PRODUIT_CREE":"PRODUIT_MODIFIE");audit.Parameters.AddWithValue("$id",saved);audit.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));audit.Parameters.AddWithValue("$details",$"Code={p.Code}; prix en unité mineure={p.SalePriceMinor}");await audit.ExecuteNonQueryAsync(ct);return saved;}catch(SqliteException ex) when(ex.SqliteErrorCode==19){throw new InvalidOperationException("La référence ou le code-barres existe déjà, ou la catégorie est invalide.",ex);}
    }
    public async Task ArchiveOrDeleteProductAsync(long productId,long userId,CancellationToken ct=default){await using var c=database.CreateConnection();await c.OpenAsync(ct);await SecurityAdministrationService.RequireManager(c,userId,ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT EXISTS(SELECT 1 FROM StockMovements WHERE ProductId=$id) OR EXISTS(SELECT 1 FROM SaleLines WHERE ProductId=$id)";Add(cmd,"$id",productId);var history=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct))!=0;cmd.CommandText=history?"UPDATE Products SET IsActive=0 WHERE Id=$id":"DELETE FROM Products WHERE Id=$id";await cmd.ExecuteNonQueryAsync(ct);}
    public async Task<IReadOnlyList<ProductStock>> GetProductsAsync(string? search=null,long? categoryId=null,bool? active=true,bool? available=null,CancellationToken ct=default){await using var c=database.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="""SELECT p.Id,p.Code,p.Name,COALESCE(SUM(l.QuantityOnHand),0),COALESCE(SUM(CASE WHEN l.IsBlocked=0 AND (l.ExpiryDate IS NULL OR l.ExpiryDate>=date('now')) THEN l.QuantityOnHand ELSE 0 END),0),p.ReorderLevel,p.SalePriceMinor FROM Products p LEFT JOIN Lots l ON l.ProductId=p.Id WHERE ($search IS NULL OR p.Name LIKE $search OR p.Code LIKE $search OR p.Barcode LIKE $search) AND ($category IS NULL OR p.CategoryId=$category) AND ($active IS NULL OR p.IsActive=$active) GROUP BY p.Id HAVING ($available IS NULL OR (($available=1 AND calculatedSellable>0) OR ($available=0 AND calculatedSellable=0))) ORDER BY p.Name""".Replace("calculatedSellable","COALESCE(SUM(CASE WHEN l.IsBlocked=0 AND (l.ExpiryDate IS NULL OR l.ExpiryDate>=date('now')) THEN l.QuantityOnHand ELSE 0 END),0)");Add(cmd,"$search",search is null?DBNull.Value:$"%{search}%");Add(cmd,"$category",(object?)categoryId??DBNull.Value);Add(cmd,"$active",active is null?DBNull.Value:active.Value?1:0);Add(cmd,"$available",available is null?DBNull.Value:available.Value?1:0);var result=new List<ProductStock>();await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))result.Add(new(r.GetInt64(0),r.GetString(1),r.GetString(2),r.GetInt32(3),r.GetInt32(4),r.GetInt32(5),r.GetInt64(6)));return result;}
    public async Task<long> ReceiveAsync(ReceiptDraft receipt,CancellationToken ct=default){if(receipt.Lines.Count==0||string.IsNullOrWhiteSpace(receipt.Reference))throw new ArgumentException("La réception doit avoir une référence et au moins une ligne.");await using var c=database.CreateConnection();await c.OpenAsync(ct);await SecurityAdministrationService.RequireManager(c,receipt.UserId,ct);await using var tx=await c.BeginTransactionAsync(ct);try{await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)tx;cmd.CommandText="INSERT INTO Receipts(SupplierId,UserId,Reference,ReceivedAt,Notes) VALUES($s,$u,$r,$d,$n);SELECT last_insert_rowid()";Add(cmd,"$s",receipt.SupplierId);Add(cmd,"$u",receipt.UserId);Add(cmd,"$r",receipt.Reference.Trim());Add(cmd,"$d",receipt.ReceivedAt.ToString("O"));Add(cmd,"$n",(object?)receipt.Notes??DBNull.Value);var rid=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));foreach(var line in receipt.Lines){if(line.Quantity<=0||line.UnitCostMinor<0||string.IsNullOrWhiteSpace(line.LotNumber))throw new ArgumentException("Chaque ligne doit avoir une quantité, un coût et un numéro de lot valides.");cmd.Parameters.Clear();cmd.CommandText="INSERT INTO Lots(ProductId,ReceiptId,LotNumber,ExpiryDate,QuantityReceived,QuantityOnHand,CostPriceMinor) VALUES($p,$r,$lot,$exp,$q,$q,$cost);SELECT last_insert_rowid()";Add(cmd,"$p",line.ProductId);Add(cmd,"$r",rid);Add(cmd,"$lot",line.LotNumber);Add(cmd,"$exp",line.ExpiryDate?.ToString("yyyy-MM-dd") is string exp?exp:DBNull.Value);Add(cmd,"$q",line.Quantity);Add(cmd,"$cost",line.UnitCostMinor);var lot=Convert.ToInt64(await cmd.ExecuteScalarAsync(ct));cmd.Parameters.Clear();cmd.CommandText="INSERT INTO ReceiptLines(ReceiptId,ProductId,LotId,Quantity,UnitCostMinor) VALUES($r,$p,$lot,$q,$cost);INSERT INTO StockMovements(ProductId,LotId,UserId,MovementType,Quantity,OccurredAt,Reference) VALUES($p,$lot,$u,'RECEPTION',$q,$d,$r)";Add(cmd,"$r",rid);Add(cmd,"$p",line.ProductId);Add(cmd,"$lot",lot);Add(cmd,"$q",line.Quantity);Add(cmd,"$cost",line.UnitCostMinor);Add(cmd,"$u",receipt.UserId);Add(cmd,"$d",receipt.ReceivedAt.ToString("O"));await cmd.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return rid;}catch{await tx.RollbackAsync(ct);throw;}}
    public async Task<long?> SelectFefoLotAsync(long productId,CancellationToken ct=default){await using var c=database.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="SELECT Id FROM Lots WHERE ProductId=$p AND QuantityOnHand>0 AND IsBlocked=0 AND (ExpiryDate IS NULL OR ExpiryDate>=date('now')) ORDER BY CASE WHEN ExpiryDate IS NULL THEN 1 ELSE 0 END,ExpiryDate LIMIT 1";Add(cmd,"$p",productId);var val=await cmd.ExecuteScalarAsync(ct);return val is null?null:Convert.ToInt64(val);}
    public async Task SellAsync(long productId,int quantity,long userId,CancellationToken ct=default){if(quantity<=0)throw new ArgumentOutOfRangeException(nameof(quantity));await using var c=database.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);try{var remaining=quantity;while(remaining>0){await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)tx;cmd.CommandText="SELECT Id,QuantityOnHand FROM Lots WHERE ProductId=$p AND QuantityOnHand>0 AND IsBlocked=0 AND (ExpiryDate IS NULL OR ExpiryDate>=date('now')) ORDER BY CASE WHEN ExpiryDate IS NULL THEN 1 ELSE 0 END,ExpiryDate LIMIT 1";Add(cmd,"$p",productId);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new InvalidOperationException("Stock vendable insuffisant.");var lot=r.GetInt64(0);var take=Math.Min(remaining,r.GetInt32(1));await r.DisposeAsync();cmd.Parameters.Clear();cmd.CommandText="UPDATE Lots SET QuantityOnHand=QuantityOnHand-$q WHERE Id=$lot;INSERT INTO StockMovements(ProductId,LotId,UserId,MovementType,Quantity,OccurredAt) VALUES($p,$lot,$u,'VENTE',-$q,$d)";Add(cmd,"$q",take);Add(cmd,"$lot",lot);Add(cmd,"$p",productId);Add(cmd,"$u",userId);Add(cmd,"$d",DateTimeOffset.Now.ToString("O"));await cmd.ExecuteNonQueryAsync(ct);remaining-=take;}await tx.CommitAsync(ct);}catch{await tx.RollbackAsync(ct);throw;}}
    public async Task BlockLotAsync(long lotId,long userId,string reason,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Un motif de blocage est obligatoire.");await using var c=database.CreateConnection();await c.OpenAsync(ct);await SecurityAdministrationService.RequireManager(c,userId,ct);await using var cmd=c.CreateCommand();cmd.CommandText="UPDATE Lots SET IsBlocked=1,BlockReason=$r WHERE Id=$id;INSERT INTO StockMovements(ProductId,LotId,UserId,MovementType,Quantity,OccurredAt,Notes) SELECT ProductId,Id,$u,'AJUSTEMENT',1,$d,$r FROM Lots WHERE Id=$id";Add(cmd,"$r",reason);Add(cmd,"$id",lotId);Add(cmd,"$u",userId);Add(cmd,"$d",DateTimeOffset.Now.ToString("O"));await cmd.ExecuteNonQueryAsync(ct);}
    public async Task AdjustLotAsync(long lotId,int newQuantity,long userId,string reason,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Un motif est obligatoire pour chaque ajustement.");await using var c=database.CreateConnection();await c.OpenAsync(ct);await SecurityAdministrationService.RequireManager(c,userId,ct);await using var tx=await c.BeginTransactionAsync(ct);await using var cmd=c.CreateCommand();cmd.Transaction=(SqliteTransaction)tx;cmd.CommandText="SELECT ProductId,QuantityOnHand FROM Lots WHERE Id=$id";Add(cmd,"$id",lotId);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new InvalidOperationException("Lot introuvable.");var product=r.GetInt64(0);var old=r.GetInt32(1);await r.DisposeAsync();var delta=newQuantity-old;if(delta==0)throw new ArgumentException("Aucun écart à ajuster.");cmd.Parameters.Clear();cmd.CommandText="UPDATE Lots SET QuantityOnHand=$q WHERE Id=$id;INSERT INTO StockMovements(ProductId,LotId,UserId,MovementType,Quantity,OccurredAt,Notes) VALUES($p,$id,$u,'AJUSTEMENT',$delta,$d,$reason);INSERT INTO StockAdjustments(ProductId,LotId,UserId,QuantityDelta,Reason,OccurredAt) VALUES($p,$id,$u,$delta,$reason,$d)";Add(cmd,"$q",newQuantity);Add(cmd,"$id",lotId);Add(cmd,"$p",product);Add(cmd,"$u",userId);Add(cmd,"$delta",delta);Add(cmd,"$reason",reason);Add(cmd,"$d",DateTimeOffset.Now.ToString("O"));await cmd.ExecuteNonQueryAsync(ct);await tx.CommitAsync(ct);}
    public async Task<IReadOnlyList<StockAlert>> GetAlertsAsync(int expiryDays=90,CancellationToken ct=default){await using var c=database.CreateConnection();await c.OpenAsync(ct);await using var cmd=c.CreateCommand();cmd.CommandText="""SELECT CASE WHEN s.sellable=0 THEN 'RUPTURE' WHEN s.sellable<=p.ReorderLevel THEN 'SEUIL' ELSE 'PEREMPTION' END,p.Id,p.Name,COALESCE(l.LotNumber,''),s.sellable,CASE WHEN s.sellable=0 THEN 'Rupture de stock' WHEN s.sellable<=p.ReorderLevel THEN 'Stock au seuil minimal' ELSE 'Péremption proche' END FROM Products p LEFT JOIN Lots l ON l.ProductId=p.Id LEFT JOIN (SELECT ProductId,SUM(CASE WHEN IsBlocked=0 AND (ExpiryDate IS NULL OR ExpiryDate>=date('now')) THEN QuantityOnHand ELSE 0 END) sellable FROM Lots GROUP BY ProductId) s ON s.ProductId=p.Id WHERE p.IsActive=1 AND (COALESCE(s.sellable,0)<=p.ReorderLevel OR (l.ExpiryDate BETWEEN date('now') AND date('now','+'||$days||' days') AND l.IsBlocked=0)) ORDER BY p.Name""";Add(cmd,"$days",expiryDays);var list=new List<StockAlert>();await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetString(0),r.GetInt64(1),r.GetString(2),r.GetString(3),r.GetInt32(4),r.GetString(5)));return list;}
    private static void Add(SqliteCommand cmd,string name,object value)=>cmd.Parameters.AddWithValue(name,value);
}
